let konkursyAdminStan={loading:false,loaded:false,error:"",state:null,entries:[],entriesLoaded:false,entriesLoading:false,entriesTotal:0,filters:{contestId:"",status:"",search:""},aiBusy:false,aiRun:null};
const KONKURS_STATUSY={draft:["Szkic","draft"],scheduled:["Zaplanowany","scheduled"],active:["Trwa","active"],paused:["Wstrzymany","paused"],review:["Ocena","review"],completed:["Zakończony","completed"],cancelled:["Anulowany","cancelled"]};
function konkursAdminStatusMeta(value){return KONKURS_STATUSY[value]||KONKURS_STATUSY.draft;}
function konkursAdminData(value){const time=Date.parse(value||"");return Number.isFinite(time)?new Date(time).toLocaleString("pl-PL",{dateStyle:"medium",timeStyle:"short"}):"—";}
function konkursAdminKwota(value){return `${Number(value||0).toLocaleString("pl-PL",{minimumFractionDigits:0,maximumFractionDigits:2})} zł`;}
function konkursyAdminSubnav(active="pulpit"){
  return adminSubnavHTML([
    {id:"pulpit",href:"#/admin/konkursy",label:"🏆 Pulpit"},{id:"lista",href:"#/admin/konkursy/lista",label:"📋 Konkursy"},{id:"nowy",href:"#/admin/konkursy/nowy",label:"✨ Kreator i Agent AI"},
    {id:"zgloszenia",href:"#/admin/konkursy/zgloszenia",label:"📝 Zgłoszenia"},{id:"ranking",href:"#/admin/konkursy/ranking",label:"📊 Ranking"},{id:"zwyciezcy",href:"#/admin/konkursy/zwyciezcy",label:"🥇 Zwycięzcy"},{id:"ustawienia",href:"#/admin/konkursy/ustawienia",label:"⚙️ Ustawienia"},
  ],active);
}
function konkursyAdminSzkielet(active,content){return adminSzkielet("/admin/konkursy",`<div class="module-page-stack contest-admin-page"><header class="contest-admin-command"><div><span class="order-pro-label">Jedno źródło prawdy • PostgreSQL</span><h1>🏆 Centrum konkursów Artway-TM</h1><p>Szkice, publikacja, zgłoszenia, weryfikacja, punkty, udostępnienia i jeden zwycięzca w jednym module.</p></div><div class="diag-actions"><a class="btn ghost" href="#/konkursy">👁️ Strona klienta</a><a class="btn ghost" href="#/admin/personalizacja/publikacje">📣 Linki promocyjne</a><a class="btn" href="#/admin/konkursy/nowy">＋ Nowy konkurs</a></div></header>${konkursyAdminSubnav(active)}${content}</div>`);}
function konkursyAdminOdswiezWidok(){if(trasa().startsWith("/admin/konkursy"))renderuj();}
async function konkursyAdminPobierz(force=false){
  if(konkursyAdminStan.loading||(!force&&konkursyAdminStan.loaded))return;
  konkursyAdminStan={...konkursyAdminStan,loading:true,error:""};konkursyAdminOdswiezWidok();
  try{const data=await chmura("contest-admin-state",{timeout:15000});konkursyAdminStan={...konkursyAdminStan,loading:false,loaded:true,error:"",state:data.state};}
  catch(error){konkursyAdminStan={...konkursyAdminStan,loading:false,loaded:true,error:error.message||"Nie udało się pobrać konkursów."};}
  konkursyAdminOdswiezWidok();
}
async function konkursyAdminPobierzZgloszenia(force=false){
  if(konkursyAdminStan.entriesLoading||(!force&&konkursyAdminStan.entriesLoaded))return;
  konkursyAdminStan={...konkursyAdminStan,entriesLoading:true};konkursyAdminOdswiezWidok();
  try{const f=konkursyAdminStan.filters,data=await chmura("contest-admin-entries",{params:{contestId:f.contestId,status:f.status,search:f.search,limit:250},timeout:15000});konkursyAdminStan={...konkursyAdminStan,entriesLoading:false,entriesLoaded:true,entries:data.entries||[],entriesTotal:Number(data.total)||0};}
  catch(error){konkursyAdminStan={...konkursyAdminStan,entriesLoading:false,error:error.message||"Nie udało się pobrać zgłoszeń."};}
  konkursyAdminOdswiezWidok();
}
function konkursyAdminZapewnijDane(entries=false){if(!konkursyAdminStan.loaded&&!konkursyAdminStan.loading)setTimeout(()=>konkursyAdminPobierz(),0);if(entries&&konkursyAdminStan.loaded&&!konkursyAdminStan.entriesLoaded&&!konkursyAdminStan.entriesLoading)setTimeout(()=>konkursyAdminPobierzZgloszenia(),0);}
function konkursAdminKpiHTML(){
  const list=konkursyAdminStan.state?.contests||[],entries=list.reduce((sum,item)=>sum+Number(item.stats?.total||0),0),review=list.reduce((sum,item)=>sum+Number(item.stats?.submitted||0),0);
  return `<section class="contest-admin-kpis"><article><span>●</span><b>${list.filter(item=>item.effectiveStatus==="active").length}</b><small>aktywnych teraz</small></article><article><span>◷</span><b>${list.filter(item=>item.effectiveStatus==="scheduled").length}</b><small>zaplanowanych</small></article><article><span>✍</span><b>${entries}</b><small>wszystkich zgłoszeń</small></article><article><span>!</span><b>${review}</b><small>do oceny</small></article><article><span>★</span><b>${list.filter(item=>item.winnerEntryId).length}</b><small>wybranych zwycięzców</small></article></section>`;
}
function konkursAdminLoadingHTML(){return konkursyAdminStan.error?`<section class="panel backend-note warn"><b>Nie udało się pobrać centrum konkursów</b><p>${esc(konkursyAdminStan.error)}</p><button class="btn" onclick="konkursyAdminPobierz(true)">Ponów</button></section>`:`<section class="panel contest-admin-loading">Ładuję konkursy i aktualne wyniki z serwera…</section>`;}
function konkursAdminWorkflowHTML(){return `<section class="panel contest-admin-workflow"><article><span>1</span><b>Agent przygotowuje szkic</b><small>Temat, zadanie, treści i promocja</small></article><i>→</i><article><span>2</span><b>Administrator sprawdza</b><small>Regulamin, daty, nagrodę i warunki</small></article><i>→</i><article><span>3</span><b>Klient wykonuje pracę</b><small>Jedno konto i jedno zgłoszenie</small></article><i>→</i><article><span>4</span><b>Ocena i wynik</b><small>Ranking dopiero po zamknięciu</small></article></section>`;}
function widokAdminKonkursyPulpit(){
  konkursyAdminZapewnijDane();if(!konkursyAdminStan.loaded)return konkursyAdminSzkielet("pulpit",konkursAdminLoadingHTML());const list=konkursyAdminStan.state.contests||[];
  return konkursyAdminSzkielet("pulpit",`${konkursAdminKpiHTML()}${konkursAdminWorkflowHTML()}<section class="contest-admin-dashboard-grid"><article class="panel contest-admin-focus"><span class="order-pro-label">NAJWAŻNIEJSZE TERAZ</span><h2>${list.some(item=>item.stats?.submitted)?"Zgłoszenia czekają na ocenę":"Możesz przygotować następny konkurs"}</h2><p>${list.some(item=>item.stats?.submitted)?"Oceń prace, sprawdź warunki udziału i dopiero po zamknięciu wybierz najwyższy poprawny wynik.":"Agent AI przygotuje kompletny szkic. Publikacja nadal wymaga Twojego osobnego potwierdzenia."}</p><div class="diag-actions"><a class="btn" href="#/admin/konkursy/${list.some(item=>item.stats?.submitted)?"zgloszenia":"nowy"}">${list.some(item=>item.stats?.submitted)?"Przejdź do oceny":"Otwórz kreator"}</a><a class="btn ghost" href="#/admin/konkursy/lista">Wszystkie konkursy</a></div></article><article class="panel contest-admin-safety"><span class="order-pro-label">STAŁE ZABEZPIECZENIA</span><ul><li>jedno konto i jeden adres na konkurs</li><li>nagroda zawsze wysyłana kurierem</li><li>brak sztucznego minimum uczestników</li><li>ranking niewidoczny podczas konkursu</li><li>AI zapisuje tylko szkic</li></ul></article></section><section class="panel"><div class="order-section-head"><div><h2>Ostatnie konkursy</h2><p class="order-detail-lead">Stan potwierdzony przez serwer</p></div><button class="btn ghost" onclick="konkursyAdminPobierz(true)">↻ Odśwież</button></div>${list.slice(0,5).map(konkursAdminWierszHTML).join("")||`<div class="empty"><h2>Nie ma jeszcze konkursu</h2><a class="btn" href="#/admin/konkursy/nowy">Utwórz pierwszy szkic</a></div>`}</section>`);
}
function konkursAdminWierszHTML(item={}){const [label,statusClass]=konkursAdminStatusMeta(item.effectiveStatus||item.status),ready=item.readiness?.ready;return `<article class="contest-admin-row"><span class="contest-admin-icon">${esc(item.icon||"🏆")}</span><div><b>${esc(item.title)}</b><small>${esc(item.frequency)} • ${konkursAdminKwota(item.prizeAmount)} • ${konkursAdminData(item.startsAt)} — ${konkursAdminData(item.endsAt)}</small></div><em class="${statusClass}">${esc(label)}</em><span><b>${Number(item.stats?.total||0)}</b><small>zgłoszeń</small></span><span><b>${Number(item.stats?.topScore||0)}</b><small>najlepszy wynik</small></span><div class="diag-actions"><a class="btn ghost" href="#/admin/konkursy/edytuj/${encodeURIComponent(item.id)}">Edytuj</a>${item.status==="draft"||item.status==="paused"?`<button class="btn" onclick="konkursAdminStatus(${jsArg(item.id)},'${item.status==="paused"?"resume":"publish"}')" ${ready?"":"disabled"}>${item.status==="paused"?"Wznów":"Opublikuj"}</button>`:item.status==="active"||item.status==="scheduled"?`<button class="btn ghost" onclick="konkursAdminStatus(${jsArg(item.id)},'pause')">Wstrzymaj</button><button class="btn" onclick="konkursAdminStatus(${jsArg(item.id)},'close')">Zamknij zgłoszenia</button>`:""}</div></article>`;}
function widokAdminKonkursyLista(){konkursyAdminZapewnijDane();if(!konkursyAdminStan.loaded)return konkursyAdminSzkielet("lista",konkursAdminLoadingHTML());const list=konkursyAdminStan.state.contests||[];return konkursyAdminSzkielet("lista",`${konkursAdminKpiHTML()}<section class="panel contest-admin-list-head"><div><span class="order-pro-label">PEŁNY REJESTR</span><h2>Wszystkie konkursy</h2><p>Publikowanie, wstrzymywanie i zamykanie są osobnymi, audytowalnymi decyzjami.</p></div><a class="btn" href="#/admin/konkursy/nowy">＋ Nowy szkic</a></section><div class="contest-admin-list">${list.map(konkursAdminWierszHTML).join("")||`<div class="panel empty">Brak konkursów.</div>`}</div>`);}
function konkursAdminRegulaminDomyslny(){return `1. Organizatorem konkursu jest Artway-TM.\n2. Uczestnik wykonuje samodzielnie zadanie opisane na stronie konkursu. Wygrywa jedna osoba z najwyższym prawidłowym wynikiem.\n3. Jedna osoba może używać jednego konta. Jeden adres zamieszkania, numer telefonu i konto mogą zostać użyte do jednego zgłoszenia w danym konkursie.\n4. Zgłoszenia automatyczne, powielone, cudze, naruszające prawo lub prawa innych osób mogą zostać odrzucone.\n5. Jeżeli konkurs wymaga zakupu lub potwierdzonych udostępnień, warunki te są sprawdzane w danych sklepu. Zwrot zakupu może oznaczać utratę spełnienia warunku zakupu.\n6. Ranking jest publikowany dopiero po zakończeniu oceny. W czasie konkursu wyniki innych osób pozostają niewidoczne.\n7. Nagroda jest wysyłana wyłącznie kurierem na zweryfikowany adres zwycięzcy.\n8. Organizator nie ustala minimalnej liczby uczestników. Jeżeli istnieje co najmniej jedno prawidłowe zgłoszenie spełniające warunki, wybierany jest jeden zwycięzca.\n9. Dane są używane wyłącznie do przeprowadzenia konkursu, przeciwdziałania nadużyciom i wysyłki nagrody.\n10. Szczegółowe terminy, zadanie, kryteria i nagroda znajdują się na stronie danego konkursu. Regulamin wymaga przeglądu i zatwierdzenia administratora przed publikacją.`;}
function konkursAdminDomyslny(templateId="weekly"){
  const template=(konkursyAdminStan.state?.templates||[]).find(item=>item.id===templateId)||{frequency:"weekly",prizeAmount:100,durationHours:168,icon:"🏆"},start=new Date(Date.now()+3600000),end=new Date(start.getTime()+Number(template.durationHours||168)*3600000),local=value=>{const d=new Date(value.getTime()-value.getTimezoneOffset()*60000);return d.toISOString().slice(0,16);};
  return {id:`contest-${Date.now().toString(36)}`,slug:"",status:"draft",frequency:template.frequency,icon:template.icon,title:"",eyebrow:"KONKURS ARTWAY-TM",description:"",taskTitle:"Zadanie konkursowe",taskPrompt:"",prizeAmount:template.prizeAmount,prizeDescription:`Nagroda o wartości ${template.prizeAmount} zł`,startsAt:local(start),endsAt:local(end),purchaseRequired:template.frequency!=="daily",purchaseMinAmount:0,minAnswerLength:40,shareRequired:true,minimumConfirmedShares:3,sharePointValue:1,purchaseBonusPoints:0,scoringInstructions:"Oceń jakość, samodzielność, pomysłowość i zgodność odpowiedzi z zadaniem.",announcementText:"",promotionPlan:"",rulesText:konkursAdminRegulaminDomyslny(),rulesApproved:false,legalReviewConfirmed:false,sharePublicationId:konkursyAdminStan.state?.settings?.sharePublicationId||"powitanie-z-polecenia"};
}
function konkursAdminPolaHTML(item={}){return `<input type="hidden" name="id" value="${esc(item.id)}"><div class="contest-form-grid"><label>Rodzaj cyklu<select name="frequency"><option value="daily">Codzienny</option><option value="weekly" ${item.frequency==="weekly"?"selected":""}>Tygodniowy</option><option value="monthly" ${item.frequency==="monthly"?"selected":""}>Miesięczny</option><option value="custom" ${item.frequency==="custom"?"selected":""}>Własny</option></select></label><label>Ikona<input name="icon" maxlength="8" value="${esc(item.icon||"🏆")}"></label><label class="wide">Tytuł konkursu<input required name="title" minlength="8" maxlength="140" value="${esc(item.title||"")}" placeholder="Np. Polska w jednym zdaniu"></label><label>Adres strony<input name="slug" maxlength="80" value="${esc(item.slug||"")}" placeholder="tworzony z tytułu"></label><label>Mały nagłówek<input name="eyebrow" maxlength="60" value="${esc(item.eyebrow||"KONKURS ARTWAY-TM")}"></label><label class="wide">Opis dla klienta<textarea required name="description" minlength="40" maxlength="1600" rows="3">${esc(item.description||"")}</textarea></label></div><fieldset><legend>2. Zadanie i punktacja</legend><div class="contest-form-grid"><label>Tytuł zadania<input required name="taskTitle" maxlength="180" value="${esc(item.taskTitle||"")}"></label><label>Minimalna długość odpowiedzi<input type="number" name="minAnswerLength" min="10" max="1000" value="${Number(item.minAnswerLength||40)}"></label><label class="wide">Dokładne zadanie<textarea required name="taskPrompt" minlength="40" maxlength="4000" rows="5">${esc(item.taskPrompt||"")}</textarea></label><label class="wide">Instrukcja oceniania dla administratora<textarea name="scoringInstructions" maxlength="1800" rows="3">${esc(item.scoringInstructions||"")}</textarea></label><label>Punkty za potwierdzone udostępnienie<input type="number" name="sharePointValue" min="0" max="100" value="${Number(item.sharePointValue||1)}"></label><label>Wymagana liczba udostępnień<input type="number" name="minimumConfirmedShares" min="0" max="100" value="${Number(item.minimumConfirmedShares??3)}"></label><label>Bonus za zakup<input type="number" name="purchaseBonusPoints" min="0" max="1000" value="${Number(item.purchaseBonusPoints||0)}"></label><label class="check"><input type="checkbox" name="shareRequired" ${item.shareRequired===false?"":"checked"}> Udostępnienia są warunkiem</label></div></fieldset><fieldset><legend>3. Nagroda, zakup i termin</legend><div class="contest-form-grid"><label>Wartość nagrody (zł)<input type="number" name="prizeAmount" min="0" max="100000" step=".01" value="${Number(item.prizeAmount||0)}"></label><label>Opis nagrody<input name="prizeDescription" maxlength="240" value="${esc(item.prizeDescription||"")}"></label><label>Start<input required type="datetime-local" name="startsAt" value="${esc(String(item.startsAt||"").slice(0,16))}"></label><label>Koniec<input required type="datetime-local" name="endsAt" value="${esc(String(item.endsAt||"").slice(0,16))}"></label><label class="check"><input type="checkbox" name="purchaseRequired" ${item.purchaseRequired?"checked":""}> Udział wymaga zakupu</label><label>Minimalny zakup (zł)<input type="number" name="purchaseMinAmount" min="0" max="100000" step=".01" value="${Number(item.purchaseMinAmount||0)}"></label></div><div class="backend-note"><b>🚚 Stała zasada:</b> nagroda jest wysyłana wyłącznie kurierem. Nie można tego osłabić w pojedynczym konkursie.</div></fieldset><fieldset><legend>4. Promocja i komunikacja</legend><div class="contest-form-grid"><label class="wide">Komunikat promocyjny<textarea name="announcementText" maxlength="1200" rows="3">${esc(item.announcementText||"")}</textarea></label><label class="wide">Plan darmowej promocji<textarea name="promotionPlan" maxlength="2400" rows="4">${esc(item.promotionPlan||"")}</textarea></label><label>Publikacja używana w linku polecającym<select name="sharePublicationId">${konkursAdminPublikacjeOpcje(item.sharePublicationId)}</select></label></div></fieldset><fieldset><legend>5. Regulamin i bramka publikacji</legend><label>Regulamin konkretnego konkursu<textarea required name="rulesText" minlength="300" maxlength="16000" rows="13">${esc(item.rulesText||konkursAdminRegulaminDomyslny())}</textarea></label><div class="contest-legal-checks"><label class="check"><input type="checkbox" name="rulesApproved" ${item.rulesApproved?"checked":""}> Zatwierdzam treść regulaminu dla tego konkursu</label><label class="check"><input type="checkbox" name="legalReviewConfirmed" ${item.legalReviewConfirmed?"checked":""}> Potwierdzam przegląd prawny przed publikacją</label></div></fieldset>`;}
function konkursAdminPublikacjeOpcje(selected=""){const list=Array.isArray(ustawienia.publikacjeKlienta)&&ustawienia.publikacjeKlienta.length?ustawienia.publikacjeKlienta:[{id:"powitanie-z-polecenia",title:"Powitanie z polecenia"}];return list.map(item=>`<option value="${esc(item.id)}" ${String(item.id)===String(selected)?"selected":""}>${esc(item.title||item.id)}</option>`).join("");}
function konkursAdminDaneFormularza(form){const f=new FormData(form),bool=name=>f.get(name)==="on";return {id:String(f.get("id")||`contest-${Date.now().toString(36)}`),slug:String(f.get("slug")||""),frequency:String(f.get("frequency")||"custom"),icon:String(f.get("icon")||"🏆"),title:String(f.get("title")||"").trim(),eyebrow:String(f.get("eyebrow")||"").trim(),description:String(f.get("description")||"").trim(),taskTitle:String(f.get("taskTitle")||"").trim(),taskPrompt:String(f.get("taskPrompt")||"").trim(),scoringInstructions:String(f.get("scoringInstructions")||"").trim(),prizeAmount:Number(f.get("prizeAmount")||0),prizeDescription:String(f.get("prizeDescription")||"").trim(),startsAt:String(f.get("startsAt")||""),endsAt:String(f.get("endsAt")||""),purchaseRequired:bool("purchaseRequired"),purchaseMinAmount:Number(f.get("purchaseMinAmount")||0),minAnswerLength:Number(f.get("minAnswerLength")||40),shareRequired:bool("shareRequired"),minimumConfirmedShares:Number(f.get("minimumConfirmedShares")||0),sharePointValue:Number(f.get("sharePointValue")||0),purchaseBonusPoints:Number(f.get("purchaseBonusPoints")||0),announcementText:String(f.get("announcementText")||"").trim(),promotionPlan:String(f.get("promotionPlan")||"").trim(),rulesText:String(f.get("rulesText")||"").trim(),rulesApproved:bool("rulesApproved"),legalReviewConfirmed:bool("legalReviewConfirmed"),sharePublicationId:String(f.get("sharePublicationId")||"powitanie-z-polecenia")};}
function konkursAgentAIHTML(){return `<section class="panel contest-ai-creator"><div class="contest-ai-head"><div><span class="order-pro-label">AGENT AI • TYLKO SZKIC DO TWOJEJ DECYZJI</span><h2>✨ Architekt nowego konkursu</h2><p>Napisz temat i grupę odbiorców. Agent przygotuje nazwę, zadanie, opis, komunikat i darmowy plan promocji — niczego sam nie opublikuje.</p></div><span class="lvl ${konkursyAdminStan.aiBusy?"lvl-ostrzezenie":"lvl-ok"}">${konkursyAdminStan.aiBusy?"pracuje":"gotowy"}</span></div><form onsubmit="konkursAgentAIPrzygotuj(event)"><label>Pomysł na konkurs<textarea required name="brief" minlength="10" maxlength="1800" rows="4" placeholder="Np. konkurs o polskich zwyczajach: uczestnik opisuje najciekawszą lokalną tradycję w maksymalnie 800 znakach"></textarea></label><div class="contest-form-grid"><label>Odbiorcy<input name="audience" maxlength="180" placeholder="np. pełnoletni klienci z Polski"></label><label>Cel<select name="goal"><option>zaangażowanie klientów</option><option>promocja zakupów</option><option>pozyskanie nowych odwiedzających</option><option>budowanie społeczności</option></select></label></div><button class="btn ai-generate-button" type="submit" ${konkursyAdminStan.aiBusy?"disabled":""}>${konkursyAdminStan.aiBusy?"⏳ Agent przygotowuje…":"✨ Przygotuj kompletny szkic"}</button></form>${konkursyAdminStan.aiRun?`<div class="contest-ai-result"><b>Agent przygotował szkic</b><p>${esc(konkursyAdminStan.aiRun.result?.summary||"")}</p><small>Sprawdź wszystkie pola poniżej. Publikacja pozostaje zablokowana do zatwierdzenia regulaminu.</small></div>`:""}</section>`;}
async function konkursAgentAIPrzygotuj(event){event.preventDefault();const form=event.target,f=new FormData(form),target=document.querySelector("[data-contest-editor]");if(!target)return;konkursyAdminStan.aiBusy=true;const button=event.submitter;if(button){button.disabled=true;button.textContent="⏳ Agent przygotowuje…";}try{const response=await chmura("agent-specialist-run",{method:"POST",body:{specialist:"campaign_copy",context:{contestIdea:String(f.get("brief")||""),audience:String(f.get("audience")||""),goal:String(f.get("goal")||""),rules:{oneWinner:true,skillTask:true,rankingAfterEnd:true,courierPrize:true,minimumConfirmedShares:3}},instruction:"Przygotuj rzetelny szkic konkursu umiejętnościowego dla Artway-TM. Nie uruchamiaj publikacji. Zadanie ma wymagać własnej pracy uczestnika, a nie losowania. Nie wymyślaj zakupu, rabatu, dat ani wartości nagrody. W polu store_announcement zapisz dokładną treść zadania, a w promotion_plan wyłącznie darmowe kanały promocji.",target:{type:"contest-draft"},source:"manual"},timeout:120000}),run=response.run||null,fields=Object.fromEntries((Array.isArray(run?.result?.fields)?run.result.fields:[]).map(field=>[String(field.key||""),String(field.value||"")])),editor=document.querySelector("[data-contest-editor]");if(!run)throw new Error("Agent nie zwrócił szkicu konkursu.");konkursyAdminStan.aiRun=run;if(editor){const set=(name,value)=>{if(editor.elements[name]&&value)editor.elements[name].value=value;};set("title",fields.campaign_name||fields.headline);set("taskTitle",fields.headline);set("description",fields.subheadline||run.result?.summary);set("taskPrompt",fields.store_announcement||run.result?.content);set("announcementText",fields.social_post||fields.cta);set("promotionPlan",fields.promotion_plan);editor.scrollIntoView({behavior:"smooth",block:"start"});}toast("Agent AI przygotował szkic do Twojego sprawdzenia ✅");}catch(error){toast(error.message||"Agent nie przygotował szkicu.");}finally{konkursyAdminStan.aiBusy=false;if(button?.isConnected){button.disabled=false;button.textContent="✨ Przygotuj kompletny szkic";}}}
function konkursAdminKreatorHTML(item,editing=false){const templates=konkursyAdminStan.state?.templates||[];return `${!editing?konkursAgentAIHTML():""}<section class="panel contest-template-picker"><div><span class="order-pro-label">SZYBKI START</span><h2>Wzory cyklu</h2><p>Zmieniają nagrodę i czas, ale nie publikują konkursu.</p></div><div>${templates.map(template=>`<button type="button" onclick="konkursAdminZastosujWzor(${jsArg(template.id)})"><span>${esc(template.icon)}</span><b>${esc(template.label)}</b><small>${Number(template.durationHours)} godz.</small></button>`).join("")}</div></section><form class="panel contest-editor" data-contest-editor onsubmit="konkursAdminZapisz(event)"><div class="order-section-head"><div><span class="order-pro-label">${editing?"EDYCJA SZKICU":"NOWY SZKIC"}</span><h2>${editing?esc(item.title):"Pełny kreator konkursu"}</h2><p class="order-detail-lead">Zapis szkicu nie uruchamia strony publicznej.</p></div><button class="btn" type="submit">💾 Zapisz szkic na serwerze</button></div><fieldset><legend>1. Informacje podstawowe</legend>${konkursAdminPolaHTML(item).split("<fieldset><legend>2.")[0]}</fieldset><fieldset><legend>2.${konkursAdminPolaHTML(item).split("<fieldset><legend>2.")[1]}</form>`;}
function widokAdminKonkursNowy(){konkursyAdminZapewnijDane();if(!konkursyAdminStan.loaded)return konkursyAdminSzkielet("nowy",konkursAdminLoadingHTML());return konkursyAdminSzkielet("nowy",konkursAdminKreatorHTML(konkursAdminDomyslny(),false));}
function widokAdminKonkursEdytuj(id){konkursyAdminZapewnijDane();if(!konkursyAdminStan.loaded)return konkursyAdminSzkielet("lista",konkursAdminLoadingHTML());const item=(konkursyAdminStan.state.contests||[]).find(entry=>String(entry.id)===String(id));if(!item)return konkursyAdminSzkielet("lista",`<section class="panel empty">Nie znaleziono konkursu.</section>`);return konkursyAdminSzkielet("lista",`${konkursAdminKreatorHTML(item,true)}<section class="panel contest-danger-zone"><div><h2>Operacje konkursu</h2><p>Usuwanie jest dostępne tylko dla pustego szkicu lub anulowanego konkursu bez zgłoszeń.</p></div><button class="btn danger" onclick="konkursAdminUsun(${jsArg(item.id)})">Usuń konkurs</button></section>`);}
function konkursAdminZastosujWzor(id){const template=(konkursyAdminStan.state?.templates||[]).find(item=>item.id===id),form=document.querySelector("[data-contest-editor]");if(!template||!form)return;const start=new Date(Date.now()+3600000),end=new Date(start.getTime()+Number(template.durationHours)*3600000),local=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);form.elements.frequency.value=template.frequency;form.elements.icon.value=template.icon;form.elements.prizeAmount.value=template.prizeAmount;form.elements.prizeDescription.value=`Nagroda o wartości ${template.prizeAmount} zł`;form.elements.startsAt.value=local(start);form.elements.endsAt.value=local(end);form.elements.purchaseRequired.checked=template.frequency!=="daily";toast(`Ustawiono wzór: ${template.label}`);}
async function konkursAdminZapisz(event){event.preventDefault();const button=event.submitter;if(button){button.disabled=true;button.textContent="Zapisuję…";}try{const data=await chmura("contest-admin-save",{method:"POST",body:{contest:konkursAdminDaneFormularza(event.target)},timeout:15000});toast(data.readiness?.ready?"Szkic jest kompletny i zapisany ✅":"Szkic zapisany — uzupełnij wskazane braki");await konkursyAdminPobierz(true);location.hash=`#/admin/konkursy/edytuj/${encodeURIComponent(data.contest.id)}`;}catch(error){toast(error.message||"Nie udało się zapisać konkursu.");if(button){button.disabled=false;button.textContent="💾 Zapisz szkic na serwerze";}}}
async function konkursAdminStatus(id,operation){const labels={publish:"opublikować",pause:"wstrzymać",resume:"wznowić",close:"zamknąć zgłoszenia",cancel:"anulować"};if(!confirm(`Czy na pewno chcesz ${labels[operation]||operation} ten konkurs?`))return;try{await chmura("contest-admin-status",{method:"POST",body:{contestId:id,operation},timeout:12000});toast("Status konkursu został zapisany na serwerze ✅");await konkursyAdminPobierz(true);}catch(error){toast(error.message||"Nie udało się zmienić statusu.");}}
async function konkursAdminUsun(id){if(!confirm("Usunąć pusty szkic konkursu? Tej operacji nie można cofnąć."))return;try{await chmura("contest-admin-delete",{method:"POST",body:{contestId:id},timeout:12000});toast("Konkurs został usunięty");await konkursyAdminPobierz(true);location.hash="#/admin/konkursy/lista";}catch(error){toast(error.message||"Nie udało się usunąć konkursu.");}}
function konkursAdminFiltryHTML(active="zgloszenia"){const contests=konkursyAdminStan.state?.contests||[],f=konkursyAdminStan.filters;return adminWyszukiwaniePanelHTML({id:`konkurs-${active}`,title:"Wyszukiwanie i filtry zgłoszeń",description:"Konkurs, status uczestnika, e-mail, nazwisko lub fragment odpowiedzi.",results:konkursyAdminStan.entriesTotal,fields:`<label>Konkurs<select onchange="konkursAdminFiltrZmien('contestId',this.value)"><option value="">Wszystkie konkursy</option>${contests.map(item=>`<option value="${esc(item.id)}" ${f.contestId===item.id?"selected":""}>${esc(item.title)}</option>`).join("")}</select></label><label>Status<select onchange="konkursAdminFiltrZmien('status',this.value)"><option value="">Każdy status</option><option value="submitted" ${f.status==="submitted"?"selected":""}>Do oceny</option><option value="approved" ${f.status==="approved"?"selected":""}>Dopuszczone</option><option value="rejected" ${f.status==="rejected"?"selected":""}>Odrzucone</option><option value="disqualified" ${f.status==="disqualified"?"selected":""}>Zdyskwalifikowane</option></select></label><label class="wide">Szukaj<input value="${esc(f.search)}" placeholder="Nazwisko, e-mail lub odpowiedź…" onkeydown="if(event.key==='Enter'){event.preventDefault();konkursAdminFiltrZmien('search',this.value)}"></label>`,actions:`<button class="btn" onclick="konkursAdminFiltrSzukaj(this)">Zastosuj</button><button class="btn ghost" onclick="konkursAdminFiltryWyczysc()">Wyczyść</button>`,active:!!(f.contestId||f.status||f.search)});}
function konkursAdminFiltrZmien(key,value){konkursyAdminStan.filters={...konkursyAdminStan.filters,[key]:String(value||"")};konkursyAdminStan.entriesLoaded=false;konkursyAdminPobierzZgloszenia(true);}
function konkursAdminFiltrSzukaj(button){const input=button.closest(".admin-search-standard-body")?.querySelector('input');konkursAdminFiltrZmien("search",input?.value||"");}
function konkursAdminFiltryWyczysc(){konkursyAdminStan.filters={contestId:"",status:"",search:""};konkursyAdminStan.entriesLoaded=false;konkursyAdminPobierzZgloszenia(true);}
function konkursAdminEntryRowHTML(entry={},ranking=false){const contest=(konkursyAdminStan.state?.contests||[]).find(item=>item.id===entry.contestId);return `<tr><td><b>${esc(entry.participantName)}</b><small>${esc(entry.email)}</small></td><td><b>${esc(contest?.title||entry.contestId)}</b><small>${konkursAdminData(entry.submittedAt)}</small></td><td class="contest-answer-cell"><details><summary>Zobacz pracę</summary><p>${esc(entry.answer)}</p></details></td><td><span class="contest-entry-status ${esc(entry.status)}">${entry.status==="submitted"?"do oceny":entry.status==="approved"?"dopuszczone":entry.status==="disqualified"?"dyskwalifikacja":"odrzucone"}</span></td><td><b>${Number(entry.shareConfirmations||0)}</b><small>potwierdzeń</small></td><td><b>${Number(entry.taskScore||0)}</b><small>ocena pracy</small></td><td><strong>${Number(entry.totalScore||0)} pkt</strong></td>${ranking?"":`<td><button class="btn" onclick="konkursAdminOtworzOcene(${jsArg(entry.id)})">Oceń</button></td>`}</tr>`;}
function konkursAdminTabelaHTML(ranking=false){const rows=konkursyAdminStan.entries;return `<div class="contest-admin-table-wrap"><table class="log-table contest-admin-table"><thead><tr><th>Uczestnik</th><th>Konkurs</th><th>Praca</th><th>Status</th><th>Udostępnienia</th><th>Ocena</th><th>Razem</th>${ranking?"":"<th>Akcja</th>"}</tr></thead><tbody>${rows.map(entry=>konkursAdminEntryRowHTML(entry,ranking)).join("")||`<tr><td colspan="8">Brak zgłoszeń spełniających filtry.</td></tr>`}</tbody></table></div>`;}
function widokAdminKonkursyZgloszenia(){konkursyAdminZapewnijDane(true);if(!konkursyAdminStan.loaded)return konkursyAdminSzkielet("zgloszenia",konkursAdminLoadingHTML());return konkursyAdminSzkielet("zgloszenia",`${konkursAdminKpiHTML()}${konkursAdminFiltryHTML("zgloszenia")}<section class="panel"><div class="order-section-head"><div><h2>📝 Zgłoszenia i moderacja</h2><p class="order-detail-lead">Punkty pracy są przyznawane przez administratora. Punkty udostępnień pochodzą z potwierdzonych linków.</p></div><button class="btn ghost" onclick="konkursyAdminPobierzZgloszenia(true)">↻ Odśwież</button></div>${konkursyAdminStan.entriesLoading?"Ładuję…":konkursAdminTabelaHTML(false)}</section>`);}
function widokAdminKonkursyRanking(){konkursyAdminZapewnijDane(true);if(!konkursyAdminStan.loaded)return konkursyAdminSzkielet("ranking",konkursAdminLoadingHTML());return konkursyAdminSzkielet("ranking",`${konkursAdminFiltryHTML("ranking")}<section class="panel contest-ranking-admin"><div class="order-section-head"><div><span class="order-pro-label">RANKING WEWNĘTRZNY</span><h2>📊 Wyniki robocze</h2><p class="order-detail-lead">Klienci nie widzą tej tabeli. Publiczny ranking pojawi się dopiero po ostatecznym wyborze zwycięzcy.</p></div></div>${konkursAdminTabelaHTML(true)}</section>`);}
function konkursAdminOtworzOcene(id){const entry=konkursyAdminStan.entries.find(item=>item.id===id);if(!entry)return;document.getElementById("contestScoreModal")?.remove();const modal=document.createElement("div");modal.id="contestScoreModal";modal.className="contest-score-modal";modal.onclick=event=>{if(event.target===modal)modal.remove();};modal.innerHTML=`<form class="panel" onsubmit="konkursAdminZapiszOcene(event,${jsArg(id)})"><header><div><span class="order-pro-label">OCENA ZGŁOSZENIA</span><h2>${esc(entry.participantName)}</h2></div><button class="btn ghost" type="button" onclick="this.closest('#contestScoreModal').remove()">✕</button></header><blockquote>${esc(entry.answer)}</blockquote><div class="contest-form-grid"><label>Ocena pracy 0–100<input required type="number" name="taskScore" min="0" max="100" step=".1" value="${Number(entry.taskScore||0)}"></label><label>Status<select name="status"><option value="submitted">Do oceny</option><option value="approved" ${entry.status==="approved"?"selected":""}>Dopuść do rankingu</option><option value="rejected" ${entry.status==="rejected"?"selected":""}>Odrzuć</option><option value="disqualified" ${entry.status==="disqualified"?"selected":""}>Dyskwalifikuj</option></select></label><label class="wide">Uzasadnienie / notatka<textarea name="moderationNote" maxlength="1200" rows="4">${esc(entry.moderationNote||"")}</textarea></label></div><button class="btn" type="submit">💾 Zapisz ocenę</button></form>`;document.body.appendChild(modal);modal.querySelector("input")?.focus();}
async function konkursAdminZapiszOcene(event,id){event.preventDefault();const f=new FormData(event.target),button=event.submitter;button.disabled=true;try{await chmura("contest-admin-score",{method:"POST",body:{entryId:id,taskScore:Number(f.get("taskScore")),status:String(f.get("status")),moderationNote:String(f.get("moderationNote")||"")},timeout:12000});document.getElementById("contestScoreModal")?.remove();konkursyAdminStan.entriesLoaded=false;await Promise.all([konkursyAdminPobierz(true),konkursyAdminPobierzZgloszenia(true)]);toast("Ocena została zapisana na serwerze ✅");}catch(error){button.disabled=false;toast(error.message||"Nie udało się zapisać oceny.");}}
function widokAdminKonkursyZwyciezcy(){konkursyAdminZapewnijDane(true);if(!konkursyAdminStan.loaded)return konkursyAdminSzkielet("zwyciezcy",konkursAdminLoadingHTML());const contests=konkursyAdminStan.state.contests||[],closed=contests.filter(item=>["review","completed"].includes(item.effectiveStatus));return konkursyAdminSzkielet("zwyciezcy",`<section class="panel contest-winner-head"><div><span class="order-pro-label">JEDEN ZWYCIĘZCA • NAJWYŻSZY PRAWIDŁOWY WYNIK</span><h2>🥇 Wybór i historia zwycięzców</h2><p>System uwzględnia ocenę pracy, potwierdzone udostępnienia, wymagany zakup i status moderacji. Nie ma minimalnej liczby uczestników.</p></div></section><div class="contest-winner-list">${closed.map(item=>{const winner=konkursyAdminStan.entries.find(entry=>entry.id===item.winnerEntryId);return `<article class="panel"><span>${esc(item.icon||"🏆")}</span><div><b>${esc(item.title)}</b><small>${item.effectiveStatus==="completed"?`Zwycięzca: ${esc(winner?.participantName||"wybrany w rejestrze")}`:"Ocena jeszcze trwa"}</small></div>${item.effectiveStatus==="review"?`<button class="btn" onclick="konkursAdminWybierzZwyciezce(${jsArg(item.id)})">Wybierz automatycznie najwyższy wynik</button>`:`<span class="lvl lvl-ok">wynik zamknięty</span>`}</article>`;}).join("")||`<div class="panel empty">Nie ma jeszcze zamkniętego konkursu.</div>`}</div>`);}
async function konkursAdminWybierzZwyciezce(id){if(!confirm("Zakończyć ocenę i wybrać jedno najwyżej punktowane, prawidłowe zgłoszenie? Publiczny ranking zostanie wtedy odsłonięty."))return;try{await chmura("contest-admin-winner",{method:"POST",body:{contestId:id},timeout:15000});toast("Zwycięzca został wybrany, a ranking zamknięty ✅");konkursyAdminStan.entriesLoaded=false;await Promise.all([konkursyAdminPobierz(true),konkursyAdminPobierzZgloszenia(true)]);}catch(error){toast(error.message||"Nie udało się wybrać zwycięzcy.");}}
function widokAdminKonkursyUstawienia(){konkursyAdminZapewnijDane();if(!konkursyAdminStan.loaded)return konkursyAdminSzkielet("ustawienia",konkursAdminLoadingHTML());const s=konkursyAdminStan.state.settings||{};return konkursyAdminSzkielet("ustawienia",`<form class="panel contest-settings" onsubmit="konkursAdminZapiszUstawienia(event)"><div class="order-section-head"><div><span class="order-pro-label">USTAWIENIA OGÓLNE</span><h2>⚙️ Bezpieczeństwo, ranking i publikacja</h2><p class="order-detail-lead">Najważniejsze zabezpieczenia są wymuszone przez serwer i nie mogą zostać przypadkowo wyłączone.</p></div><button class="btn" type="submit">💾 Zapisz ustawienia</button></div><div class="contest-settings-grid"><label class="check"><input type="checkbox" name="publicPageEnabled" ${s.publicPageEnabled?"checked":""}> Publiczny katalog konkursów aktywny</label><label class="check locked"><input checked disabled type="checkbox"> Udział wyłącznie po zalogowaniu</label><label class="check"><input type="checkbox" name="requireAddress" ${s.requireAddress?"checked":""}> Wymagaj pełnego adresu przed udziałem</label><label class="check locked"><input checked disabled type="checkbox"> Jedno konto na konkurs</label><label class="check"><input type="checkbox" name="oneAddressPerContest" ${s.oneAddressPerContest?"checked":""}> Jeden adres na konkurs</label><label class="check"><input type="checkbox" name="onePhonePerContest" ${s.onePhonePerContest?"checked":""}> Jeden telefon na konkurs</label><label class="check locked"><input checked disabled type="checkbox"> Nagrody tylko kurierem</label><label class="check"><input type="checkbox" name="manualModeration" ${s.manualModeration?"checked":""}> Każde zgłoszenie wymaga moderacji</label><label>Widoczność rankingu<select name="rankingVisibility"><option value="after_end">Dopiero po ostatecznym zakończeniu</option><option value="never" ${s.rankingVisibility==="never"?"selected":""}>Nigdy publicznie</option></select></label><label>Maksymalna długość pracy<input type="number" name="maxEntryLength" min="300" max="12000" value="${Number(s.maxEntryLength||4000)}"></label><label>Strona prywatności<input name="privacyNoticePath" value="${esc(s.privacyNoticePath||"#/prywatnosc")}"></label><label>Ogólny regulamin<input name="rulesPath" value="${esc(s.rulesPath||"#/regulamin")}"></label><label>Domyślna publikacja linku<select name="sharePublicationId">${konkursAdminPublikacjeOpcje(s.sharePublicationId)}</select></label></div><div class="backend-note"><b>Agent AI:</b> zawsze tworzy wyłącznie szkic. Publikacja wymaga osobnego kliknięcia administratora i przejścia bramki regulaminu.</div></form>`);}
async function konkursAdminZapiszUstawienia(event){event.preventDefault();const f=new FormData(event.target),button=event.submitter;button.disabled=true;try{await chmura("contest-admin-settings",{method:"POST",body:{settings:{publicPageEnabled:f.get("publicPageEnabled")==="on",requireAddress:f.get("requireAddress")==="on",oneAddressPerContest:f.get("oneAddressPerContest")==="on",onePhonePerContest:f.get("onePhonePerContest")==="on",manualModeration:f.get("manualModeration")==="on",rankingVisibility:String(f.get("rankingVisibility")),maxEntryLength:Number(f.get("maxEntryLength")),privacyNoticePath:String(f.get("privacyNoticePath")),rulesPath:String(f.get("rulesPath")),sharePublicationId:String(f.get("sharePublicationId"))}},timeout:12000});await konkursyAdminPobierz(true);toast("Ustawienia konkursów zapisane na serwerze ✅");}catch(error){button.disabled=false;toast(error.message||"Nie udało się zapisać ustawień.");}}
function widokAdminKonkursy(section="pulpit",id=""){return section==="lista"?widokAdminKonkursyLista():section==="nowy"?widokAdminKonkursNowy():section==="edytuj"?widokAdminKonkursEdytuj(id):section==="zgloszenia"?widokAdminKonkursyZgloszenia():section==="ranking"?widokAdminKonkursyRanking():section==="zwyciezcy"?widokAdminKonkursyZwyciezcy():section==="ustawienia"?widokAdminKonkursyUstawienia():widokAdminKonkursyPulpit();}

