  const f=new FormData(form),bool=name=>f.get(name)==="on",criterionIds=f.getAll("criterionId"),criterionLabels=f.getAll("criterionLabel"),criterionDescriptions=f.getAll("criterionDescription"),criterionMax=f.getAll("criterionMaxPoints"),responseIds=f.getAll("shareResponseId"),responseLabels=f.getAll("shareResponseLabel"),responsePoints=f.getAll("shareResponsePoints"),questionIds=f.getAll("quizQuestionId"),questionPrompts=f.getAll("quizPrompt"),questionPoints=f.getAll("quizPoints"),questionCorrect=f.getAll("quizCorrect"),optionA=f.getAll("quizOptionA"),optionB=f.getAll("quizOptionB"),optionC=f.getAll("quizOptionC");
