  return {id:String(f.get("id")||`contest-${Date.now().toString(36)}`),slug:String(f.get("slug")||""),frequency:String(f.get("frequency")||"custom"),icon:String(f.get("icon")||"🏆"),title:String(f.get("title")||"").trim(),eyebrow:String(f.get("eyebrow")||"").trim(),description:String(f.get("description")||"").trim(),contestType:"quiz_abc",taskTitle:String(f.get("taskTitle")||"").trim(),taskPrompt:String(f.get("taskPrompt")||"").trim(),quizQuestions,scoringInstructions:String(f.get("scoringInstructions")||"").trim(),scoringCriteria:criterionIds.map((id,index)=>({id:String(id),label:String(criterionLabels[index]||""),description:String(criterionDescriptions[index]||""),maxPoints:Number(criterionMax[index]||0)})),prizeAmount:Number(f.get("prizeAmount")||0),prizeDescription:String(f.get("prizeDescription")||"").trim(),startsAt:String(f.get("startsAt")||""),endsAt:String(f.get("endsAt")||""),resultsAnnouncementAt:String(f.get("resultsAnnouncementAt")||""),winnerConfirmationHours:Number(f.get("winnerConfirmationHours")||72),prizeDeliveryDays:Number(f.get("prizeDeliveryDays")||14),complaintDeadlineDays:Number(f.get("complaintDeadlineDays")||14),complaintResponseDays:Number(f.get("complaintResponseDays")||14),organizerName:String(f.get("organizerName")||"").trim(),organizerAddress:String(f.get("organizerAddress")||"").trim(),organizerTaxId:String(f.get("organizerTaxId")||"").trim(),contactEmail:String(f.get("contactEmail")||"").trim(),territory:String(f.get("territory")||"").trim(),minimumAge:Number(f.get("minimumAge")||18),taxNote:String(f.get("taxNote")||"").trim(),purchaseRequired:false,purchaseMinAmount:Number(f.get("purchaseMinAmount")||0),minAnswerLength:Number(f.get("minAnswerLength")||40),shareRequired:bool("shareRequired"),minimumConfirmedShares:Number(f.get("minimumConfirmedShares")||0),shareMaxPoints:null,shareResponseRules:responseIds.map((id,index)=>({id:String(id),label:String(responseLabels[index]||id),points:Number(responsePoints[index]||0)})),purchaseBonusPoints:Number(f.get("purchaseBonusPoints")||1),announcementText:String(f.get("announcementText")||"").trim(),promotionPlan:String(f.get("promotionPlan")||"").trim(),rulesText:String(f.get("rulesText")||"").trim(),rulesApproved:bool("rulesApproved"),legalReviewConfirmed:bool("legalReviewConfirmed"),sharePublicationId:String(f.get("sharePublicationId")||"powitanie-z-polecenia")};
