function konkursAdminKreatorHTML(item,editing=false){
  const templates=konkursyAdminStan.state?.templates||[],errors=item.readiness?.errors||[],readiness=editing?`<section class="contest-creator-readiness ${errors.length?"has-errors":"is-ready"}"><div><b>${errors.length?`Do publikacji pozostało: ${errors.length}`:"Szkic przeszedł bramkę kompletności"}</b><small>${errors.length?"Zapisz poprawki, a serwer sprawdzi wszystkie zasady ponownie.":"Publikacja nadal wymaga osobnej decyzji administratora."}</small></div>${errors.length?`<ul>${errors.map(error=>`<li>${esc(error)}</li>`).join("")}</ul>`:"<span>✓ gotowy</span>"}</section>`:"";
  return `${!editing?konkursAgentAIHTML():""}<section class="panel contest-template-picker"><div><span class="order-pro-label">SZYBKI START</span><h2>Wzory cyklu</h2><p>Ustawiają nagrodę, czas i termin wyników, ale niczego nie publikują.</p></div><div>${templates.map(template=>`<button type="button" onclick="konkursAdminZastosujWzor(${jsArg(template.id)})"><span>${esc(template.icon)}</span><b>${esc(template.label)}</b><small>${Number(template.durationHours)} godz.</small></button>`).join("")}</div></section>${readiness}<form class="panel contest-editor contest-editor-advanced" data-contest-editor onsubmit="konkursAdminZapisz(event)"><div class="order-section-head"><div><span class="order-pro-label">${editing?"EDYCJA PEŁNEGO SZKICU":"NOWY SZKIC • 7 KROKÓW"}</span><h2>${editing?esc(item.title):"Zaawansowany kreator konkursu"}</h2><p class="order-detail-lead">Regulamin i wyliczenie punktów powstają z tych samych ustawień serwera.</p></div><button class="btn" type="submit">💾 Zapisz i sprawdź kompletność</button></div>${konkursAdminPolaHTML(item)}</form>`;
}

function konkursAdminZastosujWzor(id){
  const template=(konkursyAdminStan.state?.templates||[]).find(item=>item.id===id),form=document.querySelector("[data-contest-editor]");if(!template||!form)return;
  const start=new Date(Date.now()+3600000),end=new Date(start.getTime()+Number(template.durationHours)*3600000),results=new Date(end.getTime()+48*3600000);
  form.elements.frequency.value=template.frequency;form.elements.icon.value=template.icon;form.elements.prizeAmount.value=template.prizeAmount;form.elements.prizeDescription.value=`Nagroda o wartości ${template.prizeAmount} zł`;form.elements.startsAt.value=konkursAdminLocalDate(start);form.elements.endsAt.value=konkursAdminLocalDate(end);form.elements.resultsAnnouncementAt.value=konkursAdminLocalDate(results);form.elements.purchaseBonusPoints.value=konkursAdminLosowyBonusZakupowy();toast(`Ustawiono wzór: ${template.label}`);
}

function konkursAdminEntryRowHTML(entry={},ranking=false){
  const contest=(konkursyAdminStan.state?.contests||[]).find(item=>item.id===entry.contestId),score=entry.scoreBreakdown||{};
  return `<tr><td><b>${esc(entry.participantName)}</b><small>${esc(entry.email)}</small></td><td><b>${esc(contest?.title||entry.contestId)}</b><small>${konkursAdminData(entry.submittedAt)}</small></td><td class="contest-answer-cell"><details><summary>${contest?.contestType==="quiz_abc"?"Zobacz odpowiedzi ABC":"Zobacz pracę"}</summary><p>${esc(entry.answer)}</p></details></td><td><span class="contest-entry-status ${esc(entry.status)}">${entry.status==="submitted"?"do kontroli":entry.status==="approved"?"dopuszczone":entry.status==="disqualified"?"dyskwalifikacja":"odrzucone"}</span></td><td><b>${Number(entry.shareConfirmations||0)} reakcji</b><small>${Number(score.sharePoints||0)} pkt${entry.shareResponses?.length?` • ${entry.shareResponses.filter(row=>row.count).map(row=>`${esc(row.label)}: ${row.count}`).join(", ")}`:""}</small></td><td><b>${Number(score.taskPoints??entry.taskScore??0)}</b><small>${contest?.contestType==="quiz_abc"?"wynik ABC — automatyczny":"ocena kryteriów"}</small></td><td><strong>${Number(entry.totalScore||0)} pkt</strong><small>${Number(score.purchasePoints||0)} pkt zakup</small></td>${ranking?"":`<td><button class="btn" onclick="konkursAdminOtworzOcene(${jsArg(entry.id)})">${contest?.contestType==="quiz_abc"?"Sprawdź":"Oceń kryteria"}</button></td>`}</tr>`;
}

function konkursAdminOtworzOcene(id){
  const entry=konkursyAdminStan.entries.find(item=>item.id===id),contest=(konkursyAdminStan.state?.contests||[]).find(item=>item.id===entry?.contestId);if(!entry||!contest)return;
  document.getElementById("contestScoreModal")?.remove();const criteria=contest.scoringCriteria||KONKURS_KRYTERIA_DOMYSLNE,scores=entry.criterionScores||{},modal=document.createElement("div");modal.id="contestScoreModal";modal.className="contest-score-modal";modal.onclick=event=>{if(event.target===modal)modal.remove();};
  const scoring=contest.contestType==="quiz_abc"?`<section class="contest-quiz-audit"><div><b>${Number(entry.quizScore??entry.taskScore??0)} / ${Number(contest.quizMaxPoints||contest.taskMaxPoints||0)} pkt</b><small>Wynik pytań ABC obliczony przez serwer — nie można go ręcznie zmienić.</small></div><details><summary>Odpowiedzi uczestnika</summary><p>${esc(entry.answer).replace(/\n/g,"<br>")}</p></details></section>`:`<div class="contest-score-criteria">${criteria.map((criterion,index)=>`<label><span><b>${esc(criterion.label)}</b><small>${esc(criterion.description||"")}</small></span><input required type="number" name="criterion__${esc(criterion.id)}" min="0" max="${Number(criterion.maxPoints)}" step=".1" value="${Number(scores[criterion.id]??(index===0?Math.min(Number(entry.taskScore||0),Number(criterion.maxPoints)):0))}"><em>/ ${Number(criterion.maxPoints)} pkt</em></label>`).join("")}</div>`;
  modal.innerHTML=`<form class="panel" onsubmit="konkursAdminZapiszOcene(event,${jsArg(id)})"><header><div><span class="order-pro-label">KONTROLA WEDŁUG REGULAMINU</span><h2>${esc(entry.participantName)}</h2><p>${esc(contest.title)}</p></div><button class="btn ghost" type="button" onclick="this.closest('#contestScoreModal').remove()">✕</button></header>${scoring}<div class="contest-score-evidence"><span><b>${Number(entry.scoreBreakdown?.sharePoints||0)} pkt</b><small>reakcje z powitania • ${Number(entry.shareConfirmations||0)} potwierdzeń</small></span><span><b>${Number(entry.scoreBreakdown?.purchasePoints||0)} pkt</b><small>zweryfikowany zakup</small></span></div><div class="contest-form-grid"><label>Status<select name="status"><option value="submitted">Do kontroli</option><option value="approved" ${entry.status==="approved"?"selected":""}>Dopuść do rankingu</option><option value="rejected" ${entry.status==="rejected"?"selected":""}>Odrzuć</option><option value="disqualified" ${entry.status==="disqualified"?"selected":""}>Dyskwalifikuj</option></select></label><label class="wide">Uzasadnienie / notatka<textarea name="moderationNote" maxlength="1200" rows="4">${esc(entry.moderationNote||"")}</textarea></label></div><button class="btn" type="submit">💾 Zapisz kontrolę</button></form>`;
  document.body.appendChild(modal);modal.querySelector("input")?.focus();
}

async function konkursAdminZapiszOcene(event,id){
  event.preventDefault();const form=event.target,f=new FormData(form),button=event.submitter,entry=konkursyAdminStan.entries.find(item=>item.id===id),contest=(konkursyAdminStan.state?.contests||[]).find(item=>item.id===entry?.contestId),criterionScores=Object.fromEntries((contest?.scoringCriteria||[]).map(criterion=>[criterion.id,Number(f.get(`criterion__${criterion.id}`)||0)]));button.disabled=true;
  try{await chmura("contest-admin-score",{method:"POST",body:{entryId:id,criterionScores,status:String(f.get("status")),moderationNote:String(f.get("moderationNote")||"")},timeout:12000});document.getElementById("contestScoreModal")?.remove();konkursyAdminStan.entriesLoaded=false;await Promise.all([konkursyAdminPobierz(true),konkursyAdminPobierzZgloszenia(true)]);toast("Ocena każdego kryterium została zapisana ✅");}catch(error){button.disabled=false;toast(error.message||"Nie udało się zapisać oceny.");}
}
